// Encode generated equipment renders for mobile delivery; composition is unchanged.
const fs=require('fs'),path=require('path'),{chromium}=require('playwright');
(async()=>{const root=path.resolve(__dirname,'..'),dir=path.join(root,'assets','studio'),files=fs.readdirSync(dir).filter(n=>n.endsWith('.png'));
const browser=await chromium.launch({executablePath:'C:/Program Files (x86)/Microsoft/Edge/Application/msedge.exe',headless:true});
try{const page=await browser.newPage();for(const name of files){const input=fs.readFileSync(path.join(dir,name));const data=await page.evaluate(async data=>{const img=new Image();img.src=data;await img.decode();const canvas=document.createElement('canvas');const scale=Math.min(1,512/Math.max(img.width,img.height));canvas.width=Math.round(img.width*scale);canvas.height=Math.round(img.height*scale);canvas.getContext('2d').drawImage(img,0,0,canvas.width,canvas.height);return canvas.toDataURL('image/webp',.85).split(',')[1];},'data:image/png;base64,'+input.toString('base64'));fs.writeFileSync(path.join(dir,name.replace('.png','.webp')),Buffer.from(data,'base64'));}console.log('Optimized '+files.length+' equipment illustrations');}finally{await browser.close();}})().catch(e=>{console.error(e);process.exitCode=1;});
